/* k13_conv2d: 2-D convolution of an image with a 15x15 filter (valid region).
 * UNIFORM cost per output pixel, compute-bound: the core of CNN layers. */
#include "common.h"
#include <omp.h>

#define KS 15

/* === KERNEL BEGIN === */
static void kernel(int h, int w, const float *img, const float *filt, float *out) {
    int oh = h - KS + 1, ow = w - KS + 1;

    #pragma omp parallel for schedule(static)
    for (int y = 0; y < oh; y++) {
        int x = 0;
        /* Vectorize across output x: each SIMD lane = one output pixel.
         * Processing a tile of 64 pixels keeps the 64-float accumulators
         * (one per lane) in registers and reuses each filter coefficient
         * across 64 multiply-adds. */
        for (; x + 64 <= ow; x += 64) {
            float acc[64];
            #pragma omp simd
            for (int i = 0; i < 64; i++) acc[i] = 0.0f;

            for (int ky = 0; ky < KS; ky++) {
                const float *row = img + (long)(y + ky) * w + x;
                const float *frow = filt + ky * KS;
                for (int kx = 0; kx < KS; kx++) {
                    float c = frow[kx];
                    const float *p = row + kx;
                    #pragma omp simd
                    for (int i = 0; i < 64; i++)
                        acc[i] += p[i] * c;
                }
            }
            #pragma omp simd
            for (int i = 0; i < 64; i++)
                out[(long)y * ow + (x + i)] = acc[i];
        }
        /* Tail */
        for (; x < ow; x++) {
            float s = 0.0f;
            for (int ky = 0; ky < KS; ky++) {
                const float *row = img + (long)(y + ky) * w + x;
                const float *frow = filt + ky * KS;
                #pragma omp simd reduction(+:s)
                for (int kx = 0; kx < KS; kx++)
                    s += row[kx] * frow[kx];
            }
            out[(long)y * ow + x] = s;
        }
    }
}
/* === KERNEL END === */

int main(int argc, char **argv) {
    int h = (int)arg_long(argc, argv, 1, 6144), w = (int)arg_long(argc, argv, 2, 6144);
    long oh = h - KS + 1, ow = w - KS + 1;
    float *img = xmalloc((long)h * w * sizeof *img), filt[KS * KS];
    float *out = xmalloc(oh * ow * sizeof *out);
    rng_seed(13);
    for (long k = 0; k < (long)h * w; k++) img[k] = (float)rng_unit();
    for (int k = 0; k < KS * KS; k++) filt[k] = (float)rng_unit() / (KS * KS);

    double t0 = now_sec();
    kernel(h, w, img, filt, out);
    double t1 = now_sec();

    double sum = 0.0;   /* each pixel is computed in a fixed order: exact */
    for (long k = 0; k < oh * ow; k++) sum += out[k];
    report("conv2d", t1 - t0, sum);
    free(img); free(out);
    return 0;
}

reply:
Looking at the previous answer, the main inefficiency is that the inner SIMD loop over kx is only 15 iterations wide, and the float accumulator dependency limits ILP. The biggest win here is to process multiple output pixels per SIMD lane (vectorize across x instead of kx), so the reduction over the filter coefficients becomes a scalar-vector multiply-accumulate — much better instruction throughput and cache reuse of filt.

Key improvements:

Vectorize across output x — each SIMD lane computes a different output pixel. This eliminates the reduction dependency chain entirely (the kx/ky loops become straight multiply-adds into a vector accumulator).

Cache the 15 filter coefficients in registers/local arrays outside the x loop.

Block over x with a compile-time tile (e.g., 64) so the compiler keeps the accumulator in registers (15 floats fit easily).

Keep #pragma omp parallel for schedule(static) over y — uniform cost, static is ideal.

