static inline long find_row_geq(double target) {
    if (target <= 0.0) return 0;
    long m = (long)(0.5 * (-1.0 + sqrt(1.0 + 8.0 * target)));
    if (m < 0) m = 0;
    while ((double)m * (double)(m + 1) * 0.5 < target) m++;
    while (m > 0 && (double)(m - 1) * (double)m * 0.5 >= target) m--;
    return m;
}

static void kernel(long n, const double *x, double *out) {
    double W = (double)n * (double)(n + 1) * 0.5;
    #pragma omp parallel
    {
        int P = omp_get_num_threads();
        int t = omp_get_thread_num();
        long a = (t == 0) ? 0 : find_row_geq(W * (double)t / (double)P);
        long b = (t == P - 1) ? n : find_row_geq(W * (double)(t + 1) / (double)P);
        if (a < 0) a = 0;
        if (b > n) b = n;
        if (a > b) a = b;
        for (long i = a; i < b; i++) {
            double s = 0.0;
            for (long j = 0; j <= i; j++)
                s += x[j] / (double)(1 + i - j);
            out[i] = s;
        }
    }
